#if UNITY_EDITOR
using NUnit.Framework;using HabitatShift.Core;using HabitatShift.LevelLabR10;using UnityEngine;using System.Collections.Generic;
namespace HabitatShift.Tests { public sealed class LevelLabR10Tests { RulesetDto R(){return R10Rules.Default;}LevelDto L(){return new LevelDto{id=99,cols=3,rows=2,habitats=new[]{new HabitatDto{id="H",color="orange",need=1,movementConstraint="FREE",anchor=new IntPair{x=0,y=0},shape=new[]{new IntPair{x=0,y=0}}}},targets=new[]{new TargetDto{id="S",color="orange",position=new FloatPair{x=1.5f,y=.5f}}},elevators=new ElevatorDto[0],obstacles=new IntPair[0]};}[Test]public void R10_R9_REAL_PAIR_ARRAY_PARSE(){var p=R10R9Adapter.Import("{\"candidateLevels\":[{\"id\":7,\"cols\":3,\"rows\":3,\"mask\":[[1,0],[2,0]],\"blocked\":[[2,2]],\"habitats\":[{\"id\":\"H\",\"color\":\"red\",\"need\":1,\"anchor\":[0,0],\"shape\":[[0,0]]}],\"targets\":[{\"id\":\"S\",\"color\":\"red\",\"position\":[1.5,0.5]}],\"ports\":[{\"id\":\"P\",\"edge\":\"top\",\"entryCell\":[2,1],\"queue\":[\"red\",\"green\"]}]}]}");Assert.AreEqual(2,p.level.playableMask.Length);Assert.AreEqual(2,p.level.elevators[0].queue.Length);Assert.AreEqual("P_Q01",p.level.elevators[0].queue[0].id);Assert.AreEqual("DOWN",p.level.elevators[0].direction);}[Test]public void R10_R9_SOURCE_ONLY_REJECTED(){Assert.Throws<System.InvalidOperationException>(()=>R10R9Adapter.Import("{\"sourceLevels\":[{\"id\":9}]}"));}[Test]public void R10_DEPENDENCY_CYCLE_SAFE(){var p=new R10Project{level=L(),dependencyGraph=new List<R10Edge>{new R10Edge{from="A",to="B"},new R10Edge{from="B",to="A"}}};var q=R10Validator.Check(p);Assert.AreEqual(0,q.dependencyDepth);Assert.IsTrue(q.findings.Exists(x=>x.code=="DEPENDENCY_CYCLE"));}[Test]public void R10_DEPENDENCY_DAG_DEPTH(){Assert.AreEqual(2,R10Validator.Depth(new List<R10Edge>{new R10Edge{from="A",to="B"},new R10Edge{from="B",to="C"}}));}[Test]public void R10_NO_SIMPLE_MOVE_NOT_FALSE_PROVEN(){var l=L();l.playableMask=new[]{new IntPair{x=0,y=0}};var p=new R10Project{level=l};Assert.AreNotEqual(R10Risk.PROVEN_DEADLOCK,R10Solver.Risk(p,R()));}[Test]public void R10_PLAYTEST_CAPTURE(){var p=new R10Playtest(L(),R(),"f");Assert.True(p.Begin("H",new Vector2(.5f,.5f)));p.Move(new Vector2(1.5f,.5f));Assert.True(p.End());Assert.AreEqual(1,p.gestures.Count);Assert.True(SolutionTraceRunner.Replay(p.Trace(),L(),R(),"f").won);p.Undo();Assert.AreEqual(0,p.gestures.Count);}}
}
#endif